export interface CacheEntry<T>{value:T;expiry:number;created:number}
export interface MemoryCacheOptions{maxSize?:number;defaultTTL?:number;checkPeriod?:number}
export class MemoryCache<T=any>{private cache:Map<string,CacheEntry<T>>;private options:Required<MemoryCacheOptions>;private cleanupTimer:NodeJS.Timeout|null=null;constructor(options:MemoryCacheOptions={}){this.cache=new Map();this.options={maxSize:options.maxSize||1000,defaultTTL:options.defaultTTL||300000,checkPeriod:options.checkPeriod||60000};this.startCleanup()}get(key:string):T|undefined{const entry=this.cache.get(key);if(!entry)return undefined;if(Date.now()>entry.expiry){this.cache.delete(key);return undefined}return entry.value}set(key:string,value:T,ttl?:number):void{if(this.cache.size>=this.options.maxSize&&!this.cache.has(key)){const firstKey=this.cache.keys().next().value;if(firstKey)this.cache.delete(firstKey)}const entry:CacheEntry<T>={value,expiry:Date.now()+(ttl||this.options.defaultTTL),created:Date.now()};this.cache.set(key,entry)}has(key:string):boolean{return this.get(key)!==undefined}delete(key:string):boolean{return this.cache.delete(key)}clear():void{this.cache.clear()}async getOrSet(key:string,factory:()=>Promise<T>,ttl?:number):Promise<T>{const cached=this.get(key);if(cached!==undefined)return cached;const value=await factory();this.set(key,value,ttl);return value}getStats():{size:number;maxSize:number;hitRate:number}{return{size:this.cache.size,maxSize:this.options.maxSize,hitRate:0}}private cleanup():void{const now=Date.now();for(const[key,entry]of this.cache.entries()){if(now>entry.expiry)this.cache.delete(key)}}private startCleanup():void{this.cleanupTimer=setInterval(()=>this.cleanup(),this.options.checkPeriod)}destroy():void{if(this.cleanupTimer){clearInterval(this.cleanupTimer);this.cleanupTimer=null}this.clear()}}export const globalCache=new MemoryCache()
